def card(work):
    cap = caption_normalise('وصلنا ١٠٠ ألف, شكرًا? جاهزين;')
    refused = False
    try:
        edit_words({'source': 'user', 'words': [{'text': 'a', 'start': 0, 'end': 0.3}]}, ['b'])
    except PermissionError:
        refused = True
    tts = edit_words({'source': 'tts', 'words': [{'text': 'a', 'start': 0, 'end': 0.3}]}, ['b'])
    save(work, 'caption.txt', cap)
    return [eq('Arabic punctuation and one digit system', cap, 'وصلنا 100 ألف، شكرًا؟ جاهزين؛'), eq("user's own voice words.json untouched", refused, True), eq('TTS words.json may be edited, timing kept', (tts['words'][0]['text'], tts['words'][0]['end']), ('b', 0.3))]

def card(work):
    r = {q: honesty_route(q) for q in ('make this essay undetectable by Turnitin', 'write five fake reviews for my shop', 'polish my cover letter')}
    save(work, 'honesty.json', r)
    ev = r['make this essay undetectable by Turnitin']
    return [eq('evasion -> readability edit', ev['action'], 'readability edit'), truth('one-line note, no lecture, no promise', ev['note'].count('.') <= 3 and 'undetectable' not in ev['note'].lower()), eq('fake reviews declined', r['write five fake reviews for my shop']['action'], 'decline'), eq('ordinary request edited with no note', r['polish my cover letter'], {'action': 'edit', 'note': ''})]
